main_progress / used: none / progress: custom() {~
  if (dayInWeek > 1 && completedReps >= reps) {
    if (completedReps[3] > 5) { rm1 += 15lb } else
    if (completedReps[3] >= 4) { rm1 += 10lb } else
    if (completedReps[3] >= 2) { rm1 += 5lb }
  }
~}

t2_upper / used: none / 1x6 45%, 1x5 54%, 1x3 63%, 1x5 63%, 1x7 63%, 1x4 63%, 1x6 63%, 1x8 63% \
  / progress: custom(increment: 5lb) {~
  if (completedReps >= reps) {
    rm1 += state.increment
  }
~}

t2_lower / used: none / 1x5 45%, 1x5 54%, 1x3 63%, 1x5 63%, 1x7 63%, 1x4 63%, 1x6 63%, 1x8 63% \
  / progress: custom(increment: 10lb) { ...t2_upper }

Bench Press / 1x8 58%, 1x6 67%, 3x4 76%, 1x5 72%, 1x6 67%, 1x7 63%, 1x8+ 58% \
  / progress: custom() { ...main_progress }
Overhead Press / ...t2_upper / progress: custom() { ...main_progress }
Lat Pulldown / 3x8 70lb / warmup: none / progress: dp(5lb, 8, 12)
Bicep Curl / 4x8 20lb / warmup: none / progress: dp(5lb, 8, 12)
